head.script:
scwin.getStyle = function(id) {
    var el = WebSquare.wUnit.getDomById($p.id + id);
    return window.getComputedStyle(el).getPropertyValue('left').replace('px', '');
}
scwin.checkVal1 = function() {
    return scwin.getStyle('Calendar1_selectbox_year') - scwin.getStyle('Calendar1_selectbox_month') > 0;
}
scwin.checkVal2 = function() {
    return scwin.getStyle('Calendar2_selectbox_year') - scwin.getStyle('Calendar2_selectbox_month') > 0;
}
scwin.checkVal3 = function() {
    return scwin.getStyle('Calendar3_selectbox_year') - scwin.getStyle('Calendar3_selectbox_month') > 0;
}
scwin.checkVal4 = function() {
    return scwin.getStyle('Calendar5_selectbox_year') - scwin.getStyle('Calendar5_selectbox_month') < 0;
}
scwin.checkVal5 = function() {
    return scwin.getStyle('Calendar6_selectbox_year') - scwin.getStyle('Calendar6_selectbox_month') < 0;
}
scwin.checkVal6 = function() {
    return scwin.getStyle('Calendar7_selectbox_year') - scwin.getStyle('Calendar7_selectbox_month') < 0;
}
scwin.unitTest = function() {
    //Unit
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    // Test step 1. Source 탭에서 Calendar1 ~ Calendar4 의 useMonthYearFormat 부분을 확인한다.
    //1. In the Source tab, check the useMonthYearFormat part of Calendar1 ~ Calendar4.
    // Verify step 1. useMonthYearFormat = 'true'
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('Calendar1').getAttribute('useMonthYearFormat')", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('Calendar2').getAttribute('useMonthYearFormat')", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('Calendar3').getAttribute('useMonthYearFormat')", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('Calendar4').getAttribute('useMonthYearFormat')", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    // Test step 2. Calendar5 ~ Calendar8 의 useMonthYearFormat 부분을 확인한다.
    //2. Check the useMonthYearFormat part of Calendar5 ~ Calendar8.
    // Verify step 2. useMonthYearFormat = 'false'
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('Calendar5').getAttribute('useMonthYearFormat')", "false");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('Calendar6').getAttribute('useMonthYearFormat')", "false");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('Calendar7').getAttribute('useMonthYearFormat')", "false");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('Calendar8').getAttribute('useMonthYearFormat')", "false");
    WebSquare.wUnit.addCommand("pause", "500");
    // Test step 3. 브라우저에서 useMonthYearFormat = 'true' 의 Calendar 를 확인한다.
    //3. In your browser, check the calendar for useMonthYearFormat = 'true'.
    // Verify step 3. '월' 이 먼저 나오고 그 다음으로 '연도' 가 표시된다.
    //3. 'Month' appears first, followed by 'Year'.
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal1()", "true");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal2()", "true");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal3()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    // Test step 4. 브라우저에서 useMonthYearFormat = 'false' 의 Calendar 를 확인한다.
    //4. Check the calendar in the browser for useMonthYearFormat = 'false'.
    // Verify step 4. '연도' 가 먼저 나오고 그 다음으로 '월' 이 표시된다.
    //4. 'Year' appears first, followed by 'Month'.
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal4()", "true");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal5()", "true");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal6()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run test and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    //Function unitTest
    //Created By: Sang.do
    //Created By: 25-Jan-2018
    //end unitTest
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
